#include <pthread.h>
#include <sched.h>
#include <sys/mman.h>

void configure_realtime_thread(int core_id, int priority_level) {
    // 1. Lock all memory into RAM to eliminate page faults
    mlockall(MCL_CURRENT | MCL_FUTURE);

    // 2. Pin thread to isolated CPU core (isolcpus kernel parameter)
    cpu_set_t cpuset;
    CPU_ZERO(&cpuset);
    CPU_SET(core_id, &cpuset);
    pthread_setaffinity_np(pthread_self(), sizeof(cpu_set_t), &cpuset);

    // 3. Set POSIX real-time FIFO scheduling policy
    struct sched_param param;
    param.sched_priority = priority_level; // e.g., 95
    pthread_setschedparam(pthread_self(), SCHED_FIFO, &param);
}

// Production-Grade Zero-Copy Packet Descriptor
struct alignas(64) PacketDescriptor {
    uint8_t*  head_ptr;      // Start of physical memory buffer
    uint8_t*  data_ptr;      // Current active protocol payload
    uint32_t  data_len;      // Payload length in bytes
    uint16_t  headroom;      // Reserved prefix for MAC/RLC headers
    uint16_t  tailroom;      // Reserved suffix for CRC/Padding
    std::atomic<uint32_t> ref_count; // For HARQ retransmissions
    uint32_t  pool_index;    // Index in fixed-size slab allocator
};

// Zero-copy subheader prepend:
void prepend_subheader(PacketDescriptor* desc, const uint8_t* hdr, uint16_t len) {
    desc->data_ptr -= len;
    desc->data_len += len;
    desc->headroom -= len;
    std::memcpy(desc->data_ptr, hdr, len);
}

// 5G NR MAC Subheader Encoder
uint8_t encode_nr_subhead(uint8_t* buf, uint8_t lcid, uint16_t sdu_len) {
    if (sdu_len < 256) {
        buf[0] = (0 << 6) | (lcid & 0x3F); // F = 0
        buf[1] = static_cast<uint8_t>(sdu_len);
        return 2;
    } else {
        buf[0] = (1 << 6) | (lcid & 0x3F); // F = 1
        buf[1] = static_cast<uint8_t>((sdu_len >> 8) & 0xFF);
        buf[2] = static_cast<uint8_t>(sdu_len & 0xFF);
        return 3;
    }
}

