uint16_t encode_sliv(uint8_t S, uint8_t L) {
    if (L == 0 || (S + L) > 14) return 0xFFFF; // Invalid
    if ((L - 1) <= 7) {
        return 14 * (L - 1) + S;
    } else {
        return 14 * (14 - L + 1) + (14 - 1 - S);
    }
}

bool decode_sliv(uint16_t sliv, uint8_t& S, uint8_t& L) {
    if (sliv > 127) return false;
    uint8_t q = sliv / 14;
    uint8_t r = sliv % 14;
    if ((q + r) <= 13) {
        L = q + 1;
        S = r;
    } else {
        L = 14 - q + 1;
        S = 14 - 1 - r;
    }
    return (S + L <= 14);
}

uint32_t encode_riv(uint32_t rb_start, uint32_t num_rbs, uint32_t bwp_size) {
    if ((num_rbs - 1) <= (bwp_size / 2)) {
        return bwp_size * (num_rbs - 1) + rb_start;
    } else {
        return bwp_size * (bwp_size - num_rbs + 1) + (bwp_size - 1 - rb_start);
    }
}

#include <cmath>
#include <algorithm>
#include <cstdint>

uint32_t calculate_tbs(uint32_t n_prb, uint8_t n_symb, uint8_t n_dmrs, 
                      uint8_t q_m, double code_rate, uint8_t layers) {
    uint32_t n_re_prime = 12 * n_symb - n_dmrs;
    uint32_t n_re = std::min<uint32_t>(156, n_re_prime) * n_prb;
    double n_info = n_re * code_rate * q_m * layers;

    if (n_info <= 3824.0) {
        // Look up in TS 38.214 Table 5.1.3.2-1
        return static_cast<uint32_t>(n_info); // Simplified lookup
    }

    int n = static_cast<int>(std::floor(std::log2(n_info - 24.0))) - 5;
    double step = std::pow(2.0, n);
    uint32_t n_info_prime = std::max<uint32_t>(3840, 
        static_cast<uint32_t>(step * std::round((n_info - 24.0) / step)));

    uint32_t k_cb = (n_info_prime > 8424 && code_rate > 0.25) ? 8448 : 3840;
    uint32_t c = (n_info_prime + 24 + (k_cb - 25)) / (k_cb - 24);
    uint32_t tbs = 8 * c * ((n_info_prime + 24 + (8 * c - 1)) / (8 * c)) - 24;
    return tbs;
}

