class OllaController {
    float delta_olla_db_{0.0f};
    const float delta_up_db_{1.0f};
    const float delta_down_db_{1.0f / 9.0f}; // 10% target BLER

public:
    void on_harq_feedback(bool is_ack) {
        if (is_ack) {
            delta_olla_db_ -= delta_down_db_;
        } else {
            delta_olla_db_ += delta_up_db_;
        }
        // Clamp to prevent unbounded drift
        delta_olla_db_ = std::clamp(delta_olla_db_, -6.0f, 6.0f);
    }

    float get_offset() const { return delta_olla_db_; }
};

#include <atomic>
#include <cstdint>
#include <optional>

template <typename T, size_t Capacity>
class LockFreeSPSCQueue {
    static_assert((Capacity & (Capacity - 1)) == 0, "Capacity must be power of two!");

    alignas(64) std::atomic<size_t> head_{0}; // Written only by Producer
    alignas(64) std::atomic<size_t> tail_{0}; // Written only by Consumer
    alignas(64) T ring_buffer_[Capacity];

public:
    bool enqueue(const T& item) {
        const size_t current_head = head_.load(std::memory_order_relaxed);
        const size_t current_tail = tail_.load(std::memory_order_acquire);

        if ((current_head - current_tail) >= Capacity) return false; // Full

        ring_buffer_[current_head & (Capacity - 1)] = item;
        head_.store(current_head + 1, std::memory_order_release);
        return true;
    }

    std::optional<T> dequeue() {
        const size_t current_tail = tail_.load(std::memory_order_relaxed);
        const size_t current_head = head_.load(std::memory_order_acquire);

        if (current_head == current_tail) return std::nullopt; // Empty

        T item = ring_buffer_[current_tail & (Capacity - 1)];
        tail_.store(current_tail + 1, std::memory_order_release);
        return item;
    }
};

